```javascript
const controller = new AbortController();
const button = document.querySelector("#save");

function handleSave() {
  console.log("saved");
}

button?.addEventListener("click", handleSave, { signal: controller.signal });
// Later, remove every listener registered with this signal.
controller.abort();
```

