const controller = new AbortController();
const options = { signal: controller.signal };

window.addEventListener("resize", updateLayout, options);
document.addEventListener("keydown", handleKey, options);
button.addEventListener("click", submit, { once: true });

function updateLayout() {}
function handleKey() {}
function submit() {}
// controller.abort() removes resize and keydown listeners.
```

